export type FrameworkCardProps = {
  title: string;
  description: string;
  leadChip?: string | null;
  overflowCount?: number;
  alwaysActive?: boolean;
};

/** PitchBots library FrameworkCardShell — display-only. */
export function FrameworkCard({
  title,
  description,
  leadChip,
  overflowCount = 0,
  alwaysActive = false,
}: FrameworkCardProps) {
  const bodyText = description.trim() || "No description";
  const isPlaceholder = !description.trim();
  const showOverflow = overflowCount > 0;

  return (
    <article
      className={cn(styles.card, alwaysActive && styles.cardAlwaysActive)}
      aria-label={title}
    >
      <div className={styles.hero}>
        <div className={styles.heroBase} aria-hidden />
        <div className={styles.heroGrid} aria-hidden />
        <div className={styles.heroTopFade} aria-hidden />

        <div className={styles.heroIllustration} aria-hidden>
          <div className={styles.docFrame}>
            <div className={styles.docIcon}>
              <FrameworkHeroIcon className={styles.docIconSvg} />
            </div>
          </div>
        </div>

        <div className={styles.heroBottomFade} aria-hidden />

        <div className={styles.heroControls}>
          <div className={styles.chips}>
            {leadChip ? (
              <span className={styles.chip} title={leadChip}>
                {leadChip}
              </span>
            ) : (
              <span aria-hidden />
            )}
            {showOverflow ? (
              <span className={cn(styles.chip, styles.chipOverflow)}>
                +{overflowCount}
              </span>
            ) : null}
          </div>
          <span aria-hidden />
        </div>
      </div>

      <div className={styles.body}>
        <div className={styles.bodyTopFade} aria-hidden />
        <div className={styles.titleRow}>
          <h2 className={styles.title} title={title}>
            {title}
          </h2>
        </div>
        <p
          className={cn(
            styles.description,
            isPlaceholder && styles.descriptionMuted,
          )}
          title={!isPlaceholder ? bodyText : undefined}
        >
          {bodyText}
        </p>
      </div>
    </article>
  );
}
